package jku.pr_dke.mymakrochef.recipe;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import lombok.Getter;
import lombok.NoArgsConstructor;

/** Eine Zutat aus rezeptplaner.ingredient. Jeder Name kommt nur einmal vor. */
@Entity
@Table(schema = "rezeptplaner", name = "ingredient")
@Getter
@NoArgsConstructor
public class Ingredient {

    // Die Nummer vergibt die Datenbank (generated by default as identity)
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "ingredient_id")
    private Integer id;

    private String name;
}
